import React, { useState, useEffect } from 'react';
import { getTelegramUser, apiRequest } from '../api';

interface Message {
  id: string;
  text: string;
  sender_type: string;
  created_at: string;
  text_preview: string;
}

interface ChatStats {
  total_messages: number;
  user_messages: number;
  assistant_messages: number;
  threads_count: number;
  keywords_count: number;
}

const ChatManagement: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [stats, setStats] = useState<ChatStats | null>(null);
  const [loading, setLoading] = useState(false);
  const [selectedMessages, setSelectedMessages] = useState<Set<string>>(new Set());
  const [showInstructions, setShowInstructions] = useState(false);

  const telegramUser = getTelegramUser();
  const requireTgId = (): string => {
    const id = telegramUser?.id?.toString();
    if (!id) throw new Error('Не найден Telegram ID');
    return id;
  };

  useEffect(() => {
    loadChatStats();
    loadRecentMessages();
  }, []);

  const loadChatStats = async () => {
    setLoading(true);
    try {
      const response = await apiRequest('/messages/stats', 'GET', null, {
        'X-Telegram-User-ID': requireTgId()
      });
      
      if (response.status === 'success') {
        setStats(response.stats);
      }
    } catch (error) {
      console.error('Ошибка загрузки статистики:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadRecentMessages = async () => {
    setLoading(true);
    try {
      const response = await apiRequest('/messages/recent?limit=20', 'GET', null, {
        'X-Telegram-User-ID': requireTgId()
      });
      
      if (response.status === 'success') {
        setMessages(response.messages || []);
      }
    } catch (error) {
      console.error('Ошибка загрузки сообщений:', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleMessageSelection = (messageId: string) => {
    const newSelected = new Set(selectedMessages);
    if (newSelected.has(messageId)) {
      newSelected.delete(messageId);
    } else {
      newSelected.add(messageId);
    }
    setSelectedMessages(newSelected);
  };

  const selectAll = () => {
    setSelectedMessages(new Set(messages.map(m => m.id)));
  };

  const clearSelection = () => {
    setSelectedMessages(new Set());
  };

  const deleteSelectedMessages = async () => {
    if (selectedMessages.size === 0) return;

    const confirmed = window.confirm(
      `Вы действительно хотите удалить ${selectedMessages.size} сообщений? 
      
ЭТО ДЕЙСТВИЕ НЕОБРАТИМО!`
    );

    if (!confirmed) return;

    setLoading(true);
    try {
      const messageIds = Array.from(selectedMessages);
      const queryParams = messageIds.map(id => `message_ids=${id}`).join('&');
      
      const response = await apiRequest(`/messages/bulk?${queryParams}`, 'DELETE', null, {
        'X-Telegram-User-ID': requireTgId()
      });
      
      if (response.status === 'success') {
        alert(`✅ Успешно удалено ${response.deleted_count} сообщений!`);
        setSelectedMessages(new Set());
        loadRecentMessages();
        loadChatStats();
      } else {
        alert(`❌ Ошибка удаления: ${response.message || 'Неизвестная ошибка'}`);
      }
    } catch (error) {
      console.error('Ошибка удаления сообщений:', error);
      alert('❌ Ошибка удаления сообщений');
    } finally {
      setLoading(false);
    }
  };

  const clearAllMessages = async () => {
    const confirmed = window.confirm(
      `⚠️ ВНИМАНИЕ! КРИТИЧЕСКИ ОПАСНАЯ ОПЕРАЦИЯ!
      
Вы хотите удалить ВСЮ историю чата НАВСЕГДА!

• Все сообщения исчезнут навсегда
• Все анализы и метаданные будут уничтожены  
• Восстановление невозможно

Введите "УДАЛИТЬ ВСЁ" для подтверждения:`
    );

    if (!confirmed) return;

    const confirmation = prompt('Введите "УДАЛИТЬ ВСЁ" для подтверждения:');
    if (confirmation !== 'УДАЛИТЬ ВСЁ') {
      alert('Операция отменена - неправильное подтверждение');
      return;
    }

    setLoading(true);
    try {
      const response = await apiRequest('/messages/clear-all', 'DELETE', null, {
        'X-Telegram-User-ID': requireTgId()
      });
      
      if (response.status === 'success') {
        alert(`✅ Успешно удалено ${response.deleted_count} сообщений!`);
        setMessages([]);
        setSelectedMessages(new Set());
        loadChatStats();
      } else {
        alert(`❌ Ошибка очистки: ${response.message || 'Неизвестная ошибка'}`);
      }
    } catch (error) {
      console.error('Ошибка очистки чата:', error);
      alert('❌ Ошибка очистки чата');
    } finally {
      setLoading(false);
    }
  };

  const syncWithTelegram = async () => {
    const confirmed = window.confirm(
      `Запустить синхронизацию с Telegram?
      
Это найдет сообщения, удаленные в Telegram UI, и удалит их из базы данных.
Операция может занять некоторое время.`
    );

    if (!confirmed) return;

    setLoading(true);
    try {
      const response = await apiRequest('/messages/sync-telegram', 'POST', null, {
        'X-Telegram-User-ID': requireTgId()
      });
      
      if (response.status === 'success') {
        alert(`✅ Синхронизация завершена!
        
📊 Результаты:
• Проверено: ${response.stats?.checked || 0} сообщений
• Удалено: ${response.stats?.deleted_from_db || 0} сообщений  
• Ошибок: ${response.stats?.errors || 0}`);
        loadRecentMessages();
        loadChatStats();
      } else {
        alert(`❌ Ошибка синхронизации: ${response.message || 'Неизвестная ошибка'}`);
      }
    } catch (error) {
      console.error('Ошибка синхронизации:', error);
      alert('❌ Ошибка синхронизации с Telegram');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50 p-4">
      <div className="max-w-4xl mx-auto">
        {/* Заголовок */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
          <h1 className="text-3xl font-bold text-gray-800 mb-2">
            🗂️ Управление чатом
          </h1>
          <p className="text-gray-600">
            Управление сообщениями, очистка базы данных и синхронизация с Telegram
          </p>
        </div>

        {/* Статистика */}
        {stats && (
          <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
            <h2 className="text-xl font-semibold text-gray-800 mb-4">📊 Статистика чата</h2>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-600">{stats.total_messages}</div>
                <div className="text-sm text-gray-600">Всего сообщений</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-green-600">{stats.user_messages}</div>
                <div className="text-sm text-gray-600">Ваши сообщения</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-purple-600">{stats.assistant_messages}</div>
                <div className="text-sm text-gray-600">Ответы бота</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-orange-600">{stats.threads_count}</div>
                <div className="text-sm text-gray-600">Диалогов</div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-pink-600">{stats.keywords_count}</div>
                <div className="text-sm text-gray-600">Ключевых слов</div>
              </div>
            </div>
          </div>
        )}

        {/* Инструкции */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold text-gray-800">📖 Инструкции по удалению</h2>
            <button
              onClick={() => setShowInstructions(!showInstructions)}
              className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors"
            >
              {showInstructions ? 'Скрыть' : 'Показать'}
            </button>
          </div>
          {showInstructions && (
            <div className="bg-gray-50 rounded-lg p-4 space-y-3">
              <div className="border-l-4 border-green-500 pl-4">
                <h3 className="font-semibold text-green-700">✅ Рекомендуемые способы удаления:</h3>
                <ul className="list-disc list-inside text-sm text-gray-700 mt-2 space-y-1">
                  <li><code>/select_delete</code> - выбор из списка последних сообщений</li>
                  <li><code>/delete_last 5</code> - удаление последних N сообщений</li>
                  <li>Этот интерфейс - для массового управления</li>
                </ul>
              </div>
              <div className="border-l-4 border-red-500 pl-4">
                <h3 className="font-semibold text-red-700">❌ НЕ рекомендуется:</h3>
                <ul className="list-disc list-inside text-sm text-gray-700 mt-2 space-y-1">
                  <li>Удаление через интерфейс Telegram (долгий тап → Delete)</li>
                  <li>Telegram не уведомляет бота об удалении</li>
                  <li>Сообщения остаются в базе данных!</li>
                </ul>
              </div>
              <div className="border-l-4 border-yellow-500 pl-4">
                <h3 className="font-semibold text-yellow-700">⚠️ Если удалили через Telegram UI:</h3>
                <p className="text-sm text-gray-700 mt-2">
                  Используйте кнопку "Синхронизация с Telegram" ниже для очистки БД
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Действия */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">⚡ Быстрые действия</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <button onClick={syncWithTelegram} disabled={loading} className="flex items-center justify-center px-4 py-3 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors disabled:opacity-50">🔄 Синхронизация с Telegram</button>
            <button onClick={() => loadRecentMessages()} disabled={loading} className="flex items-center justify-center px-4 py-3 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors disabled:opacity-50">🔄 Обновить список</button>
            <button onClick={clearAllMessages} disabled={loading} className="flex items-center justify-center px-4 py-3 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors disabled:opacity-50">🗑️ ОЧИСТИТЬ ВСЁ</button>
          </div>
        </div>

        {/* Список сообщений */}
        <div className="bg-white rounded-lg shadow-lg p-6">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold text-gray-800">📝 Последние сообщения</h2>
            <div className="flex gap-2">
              <button onClick={selectAll} className="px-3 py-1 text-sm bg-gray-200 text-gray-700 rounded hover:bg-gray-300 transition-colors">Выбрать все</button>
              <button onClick={clearSelection} className="px-3 py-1 text-sm bg-gray-200 text-gray-700 rounded hover:bg-gray-300 transition-colors">Снять выбор</button>
              {selectedMessages.size > 0 && (
                <button onClick={deleteSelectedMessages} disabled={loading} className="px-3 py-1 text-sm bg-red-500 text-white rounded hover:bg-red-600 transition-colors disabled:opacity-50">Удалить выбранные ({selectedMessages.size})</button>
              )}
            </div>
          </div>

          {loading ? (
            <div className="text-center py-8">
              <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
              <p className="mt-2 text-gray-600">Загрузка...</p>
            </div>
          ) : messages.length === 0 ? (
            <div className="text-center py-8 text-gray-500">📭 Нет сообщений для отображения</div>
          ) : (
            <div className="space-y-3">
              {messages.map((message) => (
                <div key={message.id} className={`border rounded-lg p-4 cursor-pointer transition-colors ${selectedMessages.has(message.id) ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-gray-300'}`} onClick={() => toggleMessageSelection(message.id)}>
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-xl">{message.sender_type === 'user' ? '👤' : '🤖'}</span>
                        <span className="text-sm text-gray-500">{new Date(message.created_at).toLocaleString('ru-RU')}</span>
                        <span className="text-xs text-gray-400">ID: {message.id.slice(0, 8)}...</span>
                      </div>
                      <p className="text-gray-800">{message.text_preview || message.text}</p>
                    </div>
                    <div className="ml-4">
                      <input type="checkbox" checked={selectedMessages.has(message.id)} onChange={() => toggleMessageSelection(message.id)} className="w-5 h-5 text-blue-600" />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ChatManagement;
